//Actual420ea0 two-fort construction and41f520 four-pool draw callback.
//41f610 executes; rand/420200/41dbf0 are recorded leaves as in kernel oracle.
import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZV41FortFragmentsOracle2 extends GhidraScript{
 static final long S=0x7fff0000L,RET=0x12345000L,RAND=RET+4096,P=0x595d06L,Q=0x1800000L;
 long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}void set(byte[]b,int a,int n,long v){for(int i=0;i<n;i++)b[a+i]=(byte)(v>>(i*8));}int hash(byte[]b){int h=0x811c9dc5;for(byte v:b)h=(h^(v&255))*16777619;return h;}String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format("%02x",v&255));return s.toString();}void resume(EmulatorHelper e)throws Exception{long sp=e.readRegister("ESP").longValue(),ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}void start(EmulatorHelper e,long entry)throws Exception{put(e,S,4,RET);e.writeRegister("ESP",S);if(!e.run(toAddr(entry),null,monitor))throw new Exception(e.getLastError());}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<32;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{byte[]old=new byte[3600];for(int pool=0;pool<4;pool++)for(int slot=0;slot<50;slot++){int at=pool*900+slot*18;for(int j=0;j<18;j++)old[at+j]=(byte)(s*19+pool*23+slot*13+j*7);set(old,at,2,slot<new int[]{0,1,25,49,50}[s%5]?100+slot:-1);set(old,at+2,2,200);set(old,at+8,2,120);set(old,at+10,2,9999);old[at+14]=4;}e.writeMemory(toAddr(P),old);for(int i=0;i<4;i++){put(e,0x622d54+i*4,2,new int[]{400,-32768,32767,0}[s/5%4]+i*32);put(e,0x622d56+i*4,2,500+i*32);int current=new int[]{0,1,9,900,32767,-1,-32768,100}[s%8]+i*9;put(e,0x622d64+i*4,2,current);put(e,0x622d66+i*4,2,current+new int[]{0,1,100,32767}[s/8%4]);}e.setBreakpoint(toAddr(RET));start(e,0x420ea0);byte[]constructed=e.readMemory(toAddr(P),3600);StringBuilder templates=new StringBuilder("[");for(int i=0;i<50;i++){int x=(short)read(e,0x47b5f0+i*12,2);if(x==-1)break;if(i>0)templates.append(',');templates.append('[');for(int j=0;j<6;j++){if(j>0)templates.append(',');templates.append((short)read(e,0x47b5f0+i*12+j*2,2));}templates.append(']');}templates.append(']');for(int tick=0;tick<3;tick++){put(e,0x62b3a4,4,Q);put(e,0x622cb8,4,0);put(e,0x498c24,2,800);put(e,0x498c20,2,600);put(e,0x622dc4,1,s&1);put(e,0x4a6e72,1,13);put(e,0x4740ac,4,RAND);for(long a:new long[]{RAND,0x41f610,0x420200,0x41dbf0})e.setBreakpoint(toAddr(a));start(e,0x41f520);int crt=0,blast=0,spark=0,calls=0;StringBuilder args=new StringBuilder("[");while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue();if(pc==0x41f610){if(calls++>0)args.append(',');args.append('[').append(e.readRegister("ECX").longValue()).append(',').append((short)e.readRegister("EDX").intValue()).append(']');if(!e.step(monitor)||!e.run(monitor))throw new Exception(e.getLastError());continue;}if(pc==RAND)e.writeRegister("EAX",(s*3571+crt++*131+0x1743)&32767);else if(pc==0x420200)blast++;else if(pc==0x41dbf0)spark++;else throw new Exception("unexpected"+Long.toHexString(pc));resume(e);}args.append(']');int draws=(int)((read(e,0x62b3a4,4)-Q)/8);out.println("{\"scenario\":"+s+",\"tick\":"+tick+",\"before\":"+(hash(old)&0xffffffffL)+",\"constructed\":\""+hex(constructed)+"\",\"constructHash\":"+(hash(constructed)&0xffffffffL)+",\"after\":\""+hex(e.readMemory(toAddr(P),3600))+"\",\"afterHash\":"+(hash(e.readMemory(toAddr(P),3600))&0xffffffffL)+",\"draws\":"+draws+",\"queue\":\""+hex(draws==0?new byte[0]:e.readMemory(toAddr(Q),draws*8))+"\",\"crt\":"+crt+",\"blast\":"+blast+",\"spark\":"+spark+",\"calls\":"+calls+",\"args\":"+args+",\"flag\":"+read(e,0x4a6e72,1)+",\"templates\":"+templates+"}");}}finally{e.dispose();}}}}
}
